static size_t RegionOf(Appliances_Washer_State state) {
    return kRegionOf[state];
}

static size_t FirstRegionOf(Appliances_Washer_State state) {
    return kFirstRegion[state];
}

static size_t RegionsOf(Appliances_Washer_State state) {
    return kRegionsOf[state];
}

static bool IsFinalState(Appliances_Washer_State state) {
    return state != Appliances_Washer_State_None && kIsFinal[state];
}

Appliances_Washer_State Appliances_Washer_ParentOf(Appliances_Washer_State state) {
    return state == Appliances_Washer_State_None ? Appliances_Washer_State_None : kParent[state];
}

const char* Appliances_Washer_StateName(Appliances_Washer_State state) {
    return state == Appliances_Washer_State_None ? "None" : kStateNames[state];
}

const char* Appliances_Washer_EventName(Appliances_Washer_Event event) {
    return kEventNames[event];
}

static void StartTimers(Appliances_Washer* m, Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Washing:
            ++m->timerGeneration[0];
            m->timerArmed[0] = true;
            m->hooks->StartTimer(m->context, Appliances_Washer_Event_Washing_After30000ms, 30000u, m->timerGeneration[0]);
            break;
        case Appliances_Washer_State_Rinsing:
            ++m->timerGeneration[1];
            m->timerArmed[1] = true;
            m->hooks->StartTimer(m->context, Appliances_Washer_Event_Rinsing_After20000ms, 20000u, m->timerGeneration[1]);
            break;
        default:
            break;
    }
}

static void CancelTimers(Appliances_Washer* m, Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Washing:
            m->timerArmed[0] = false;
            m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Washing_After30000ms);
            break;
        case Appliances_Washer_State_Rinsing:
            m->timerArmed[1] = false;
            m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Rinsing_After20000ms);
            break;
        default:
            break;
    }
}

static int TimerIndex(Appliances_Washer_Event event) {
    switch (event) {
        case Appliances_Washer_Event_Washing_After30000ms:
            return 0;
        case Appliances_Washer_Event_Rinsing_After20000ms:
            return 1;
        default:
            return -1;
    }
}

typedef void (*Handler)(Appliances_Washer* m);

