static const Handler kEntry[Appliances_Washer_StateCount] = {
    NULL,   /* Idle */
    Entry_Running,   /* Running */
    Entry_Washing,   /* Washing */
    NULL,   /* Rinsing */
    Entry_Spinning,   /* Spinning */
    NULL,   /* ProgramDone */
    Entry_Heating,   /* Heating */
    NULL,   /* Holding */
    NULL,   /* HeaterDone */
    Entry_Error,   /* Error */
};
static const Handler kExit[Appliances_Washer_StateCount] = {
    NULL,   /* Idle */
    Exit_Running,   /* Running */
    NULL,   /* Washing */
    NULL,   /* Rinsing */
    Exit_Spinning,   /* Spinning */
    NULL,   /* ProgramDone */
    Exit_Heating,   /* Heating */
    NULL,   /* Holding */
    NULL,   /* HeaterDone */
    NULL,   /* Error */
};
static void Init_2(Appliances_Washer* m) {
    m->hooks->setTemperature(m->context);
}

/* owner, initial target, initial action; row r - 1 describes region r */
static const struct { Appliances_Washer_State owner; Appliances_Washer_State initial; Handler action; } kRegions[Appliances_Washer_RegionCount - 1] = {
    { Appliances_Washer_State_Running, Appliances_Washer_State_Washing, NULL },   /* region 1 */
    { Appliances_Washer_State_Running, Appliances_Washer_State_Heating, Init_2 },   /* region 2 */
};

static void OnEntry(Appliances_Washer* m, Appliances_Washer_State state) {
    if (kEntry[state] != NULL) {
        kEntry[state](m);
    }
}

static void OnExit(Appliances_Washer* m, Appliances_Washer_State state) {
    if (kExit[state] != NULL) {
        kExit[state](m);
    }
}

static Appliances_Washer_State Innermost(const Appliances_Washer* m, Appliances_Washer_State state) {
    while (state != Appliances_Washer_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Appliances_Washer_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static bool AllRegionsFinal(const Appliances_Washer* m, Appliances_Washer_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (!IsFinalState(m->active[region])) {
            return false;
        }
    }
    return true;
}

static void MarkCompletion(Appliances_Washer* m, Appliances_Washer_State state) {
    const Appliances_Washer_State owner = kCompletion[state];
    if (owner != Appliances_Washer_State_None && (owner == state || AllRegionsFinal(m, owner))) {
        m->pending[owner] = true;
    }
}

static void ExitState(Appliances_Washer* m, Appliances_Washer_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Appliances_Washer_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    CancelTimers(m, state);
    OnExit(m, state);
    m->active[RegionOf(state)] = Appliances_Washer_State_None;
    m->exited = state;
}

static void EnterState(Appliances_Washer* m, Appliances_Washer_State state) {
    m->active[RegionOf(state)] = state;
    OnEntry(m, state);
    StartTimers(m, state);
}

static void EnterRegion(Appliances_Washer* m, size_t region) {
    if (kRegions[region - 1].action != NULL) {
        kRegions[region - 1].action(m);
    }
    EnterDown(m, kRegions[region - 1].owner, kRegions[region - 1].initial);
}

static void EnterDefault(Appliances_Washer* m, Appliances_Washer_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
    if (RegionsOf(state) == 0) {
        MarkCompletion(m, state);
    }
}

static void EnterDown(Appliances_Washer* m, Appliances_Washer_State from, Appliances_Washer_State target) {
    Appliances_Washer_State state = target;
    Appliances_Washer_State next = Appliances_Washer_State_None;
    size_t region;
    while (Appliances_Washer_ParentOf(state) != from) {
        next = state;
        state = Appliances_Washer_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Appliances_Washer_State_None) {
        EnterDefault(m, state);
        return;
    }
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (region == RegionOf(next)) {
            EnterDown(m, state, target);
        } else {
            EnterRegion(m, region);
        }
    }
}

typedef bool (*GuardFn)(Appliances_Washer* m);

static void Transition_0(Appliances_Washer* m) {
    m->hooks->fillWater(m->context);
}

static void Transition_2(Appliances_Washer* m) {
    m->hooks->beep(m->context);
}

static void Transition_3(Appliances_Washer* m) {
    m->hooks->drain(m->context);
}

static void Transition_4(Appliances_Washer* m) {
    m->hooks->drain(m->context);
}

static void Transition_11(Appliances_Washer* m) {
    m->hooks->adjust(m->context, ((const Appliances_Washer_SetTempArgs*)m->args)->celsius);
}

static bool Guard_12(Appliances_Washer* m) {
    return m->hooks->isCool(m->context);
}

typedef struct {
    Appliances_Washer_State source;
    Appliances_Washer_Event event;
    GuardFn guard;
    Handler action;
    Appliances_Washer_State target;   /* None for internal transitions */
    Appliances_Washer_State lca;
} TransitionRow;

/* source, event, guard, action, target, least common ancestor */
static const TransitionRow kTransitions[13] = {
    { Appliances_Washer_State_Idle, Appliances_Washer_Event_Start, NULL, Transition_0, Appliances_Washer_State_Running, Appliances_Washer_State_None },
    { Appliances_Washer_State_Idle, Appliances_Washer_Event_QuickRinse, NULL, NULL, Appliances_Washer_State_Rinsing, Appliances_Washer_State_None },
    { Appliances_Washer_State_Running, Appliances_Washer_Event_Completion, NULL, Transition_2, Appliances_Washer_State_Idle, Appliances_Washer_State_None },
    { Appliances_Washer_State_Running, Appliances_Washer_Event_Cancel, NULL, Transition_3, Appliances_Washer_State_Idle, Appliances_Washer_State_None },
    { Appliances_Washer_State_Washing, Appliances_Washer_Event_Washing_After30000ms, NULL, Transition_4, Appliances_Washer_State_Rinsing, Appliances_Washer_State_Running },
    { Appliances_Washer_State_Rinsing, Appliances_Washer_Event_Rinsing_After20000ms, NULL, NULL, Appliances_Washer_State_Spinning, Appliances_Washer_State_Running },
    { Appliances_Washer_State_Spinning, Appliances_Washer_Event_Spun, NULL, NULL, Appliances_Washer_State_ProgramDone, Appliances_Washer_State_Running },
    { Appliances_Washer_State_Heating, Appliances_Washer_Event_TempReached, NULL, NULL, Appliances_Washer_State_Holding, Appliances_Washer_State_Running },
    { Appliances_Washer_State_Heating, Appliances_Washer_Event_Overheat, NULL, NULL, Appliances_Washer_State_Error, Appliances_Washer_State_None },
    { Appliances_Washer_State_Holding, Appliances_Washer_Event_TempDropped, NULL, NULL, Appliances_Washer_State_Heating, Appliances_Washer_State_Running },
    { Appliances_Washer_State_Holding, Appliances_Washer_Event_Spun, NULL, NULL, Appliances_Washer_State_HeaterDone, Appliances_Washer_State_Running },
    { Appliances_Washer_State_Holding, Appliances_Washer_Event_SetTemp, NULL, Transition_11, Appliances_Washer_State_None, Appliances_Washer_State_Running },
    { Appliances_Washer_State_Error, Appliances_Washer_Event_Reset, Guard_12, NULL, Appliances_Washer_State_Idle, Appliances_Washer_State_None },
};

static bool TryRow(Appliances_Washer* m, const TransitionRow* row) {
    if (row->guard != NULL && !row->guard(m)) {
        return false;
    }
    if (row->target == Appliances_Washer_State_None) {
        if (row->action != NULL) {
            row->action(m);
        }
        return true;
    }
    Appliances_Washer_State root = row->source;
    while (Appliances_Washer_ParentOf(root) != row->lca) {
        root = Appliances_Washer_ParentOf(root);
    }
    ExitState(m, root);
    if (row->action != NULL) {
        row->action(m);
    }
    EnterDown(m, row->lca, row->target);
    return true;
}

static bool HandleEvent(Appliances_Washer* m, Appliances_Washer_State state, Appliances_Washer_Event event) {
    size_t i;
    for (i = 0; i < 13; ++i) {
        if (kTransitions[i].source == state && kTransitions[i].event == event && TryRow(m, &kTransitions[i])) {
            return true;
        }
    }
    return false;
}

static void RunCompletions(Appliances_Washer* m) {
    for (;;) {
        size_t index = 0;
        while (index < Appliances_Washer_StateCount && !m->pending[index]) {
            ++index;
        }
        if (index == Appliances_Washer_StateCount) {
            return;
        }
        m->pending[index] = false;
        if (m->active[RegionOf((Appliances_Washer_State)index)] == (Appliances_Washer_State)index) {
            HandleEvent(m, (Appliances_Washer_State)index, Appliances_Washer_Event_Completion);
        }
    }
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Appliances_Washer* m, Appliances_Washer_State state, Appliances_Washer_Event event) {
    bool handled = false;
    Appliances_Washer_State s;
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Appliances_Washer_State_None && DispatchState(m, m->active[region], event)) {
            handled = true;
            /* Stop if the transition exited `state`, even if it entered it again. */
            for (s = state; s != Appliances_Washer_State_None; s = Appliances_Washer_ParentOf(s)) {
                if (s == m->exited) {
                    return true;
                }
            }
        }
    }
    return handled || HandleEvent(m, state, event);
}

static bool DispatchCore(Appliances_Washer* m, Appliances_Washer_Event event) {
    const int timer = TimerIndex(event);
    if (timer >= 0) {
        m->timerArmed[timer] = false;   /* a timer fires once */
    }
    m->exited = Appliances_Washer_State_None;
    if (m->active[0] != Appliances_Washer_State_None && DispatchState(m, m->active[0], event)) {
        RunCompletions(m);
        return true;
    }
    return false;
}

void Appliances_Washer_Init(Appliances_Washer* m, const Appliances_Washer_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Appliances_Washer_RegionCount; ++i) {
        m->active[i] = Appliances_Washer_State_None;
    }
    m->exited = Appliances_Washer_State_None;
    for (i = 0; i < Appliances_Washer_StateCount; ++i) {
        m->pending[i] = false;
    }
    for (i = 0; i < Appliances_Washer_TimerCount; ++i) {
        m->timerGeneration[i] = 0;
        m->timerArmed[i]      = false;
    }
    m->args = NULL;
}

void Appliances_Washer_Start(Appliances_Washer* m) {
    size_t i;
    m->hooks->Lock(m->context);
    if (m->timerArmed[0]) {
        m->timerArmed[0] = false;
        ++m->timerGeneration[0];
        m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Washing_After30000ms);
    }
    if (m->timerArmed[1]) {
        m->timerArmed[1] = false;
        ++m->timerGeneration[1];
        m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Rinsing_After20000ms);
    }
    for (i = 0; i < Appliances_Washer_RegionCount; ++i) {
        m->active[i] = Appliances_Washer_State_None;
    }
    for (i = 0; i < Appliances_Washer_StateCount; ++i) {
        m->pending[i] = false;
    }
    EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Idle);
    RunCompletions(m);
    m->hooks->Unlock(m->context);
}

bool Appliances_Washer_Dispatch(Appliances_Washer* m, Appliances_Washer_Event event) {
    bool handled = false;
    m->hooks->Lock(m->context);
    if (event != Appliances_Washer_Event_SetTemp && event != Appliances_Washer_Event_Completion) {
        m->args = NULL;
        handled = DispatchCore(m, event);
        m->args = NULL;
    }
    m->hooks->Unlock(m->context);
    return handled;
}

bool Appliances_Washer_DispatchSetTemp(Appliances_Washer* m, int celsius) {
    bool handled;
    Appliances_Washer_SetTempArgs args;
    args.celsius = celsius;
    m->hooks->Lock(m->context);
    m->args = &args;
    handled = DispatchCore(m, Appliances_Washer_Event_SetTemp);
    m->args = NULL;
    m->hooks->Unlock(m->context);
    return handled;
}

bool Appliances_Washer_DispatchTimeout(Appliances_Washer* m, Appliances_Washer_Event timeout, unsigned generation) {
    bool handled = false;
    const int index = TimerIndex(timeout);
    m->hooks->Lock(m->context);
    if (index >= 0 && m->timerArmed[index] && m->timerGeneration[index] == generation) {
        m->args = NULL;
        handled = DispatchCore(m, timeout);
        m->args = NULL;
    }
    m->hooks->Unlock(m->context);
    return handled;
}

Appliances_Washer_State Appliances_Washer_Current(const Appliances_Washer* m) {
    Appliances_Washer_State result;
    m->hooks->Lock(m->context);
    result = Innermost(m, m->active[0]);
    m->hooks->Unlock(m->context);
    return result;
}

bool Appliances_Washer_IsIn(const Appliances_Washer* m, Appliances_Washer_State state) {
    bool result;
    m->hooks->Lock(m->context);
    result = state != Appliances_Washer_State_None && m->active[RegionOf(state)] == state;
    m->hooks->Unlock(m->context);
    return result;
}

bool Appliances_Washer_IsFinished(const Appliances_Washer* m) {
    bool result;
    m->hooks->Lock(m->context);
    result = ((void)m, false);
    m->hooks->Unlock(m->context);
    return result;
}

